(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["hr"] = {"ui":{"skip":"Preskoči na sadržaj","back":"← Natrag na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Odaberi jezik","lang.search":"Traži jezike","lang.none":"Nijedan jezik ne odgovara","lang.notYet":"{name} još nije preveden","theme.aria":"Promijeni temu: svijetla, tamna ili crna","theme.toLight":"Prebaci na svijetlu temu","theme.toDark":"Prebaci na tamnu temu","theme.toBlack":"Prebaci na crnu temu (prava crna, ugodna za OLED ekrane)","words.underline":"Podcrtaj ove riječi na stranici","words.underlineHelp":"Prijeđi mišem preko riječi s točkastom crtom ili je dodirni da vidiš što znači.","words.col.todo":"Kartice odabrane za sada: tim sljedeće kreće s njima.","words.col.doing":"Neki AI trenutačno radi na ovoj kartici.","words.col.review":"Jedan je AI završio posao; drugi ga provjerava prije nego stigne do tebe.","words.col.verify":"Čeka se tebe: isprobaj i reci radi li.","words.col.team":"Tvoje bilješke ili odgovori, koji čekaju da ih tim preuzme.","words.col.done":"Gotovo i prihvaćeno.","index.title":"AI-gile: tvoj AI razvojni tim, na jednoj ploči","index.description":"AI-gile je kanban ploča za AI timove koji programiraju. Rade dok ti spavaš; tebi ostaje jedna kratka hrpa stvari koje trebaš odlučiti, testirati i prihvatiti.","hero.logoAlt":"Ikona AI-gile ploče","hero.h1.html":"Tvoj AI razvojni tim, na jednoj&nbsp;ploči.","hero.alpha":"🐣 Zatvorena pre-alfa","hero.alphaTitle":"Rano je i nedovršeno: hvala što isprobavaš!","hero.lede":"Grade dok ti spavaš. Budiš se uz jednu kratku hrpu: nekoliko pitanja, nekoliko stvari za testiranje, jedan ili dva ljubičasta dijamanta. Klikneš, prihvatiš, vratiš se kavi.","dl.windows":"Windows aplikacija","dl.browser":"Pokreni u pregledniku","dl.messenger":"📱 Messenger za tvoj mobitel","dl.soon":"Uskoro","dl.notify":"🔔 Javi mi kad se otvori","dl.notifySmall":"Alfa ili beta","hero.secondary":"Agile, ali timu ne treba stand-up kava. (Stand-up ipak održavaju.)","pitch.h2":"AI-gile u onoliko riječi koliko želiš","pitch.lede":"Odaberi duljinu, od jedne riječi do 144. Svaka duljina ima svoj opis, napisan baš za tu veličinu. Povuci klizač ili koristi strelice.","pitch.rangeLabel":"Duljina u riječima","pitch.dice":"🎲 druga verzija","pitch.words.one":"{n} riječ","pitch.words.other":"{n} riječi","pitch.letters.one":"{n} slovo","pitch.letters.other":"{n} slova","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakova","count.line.html.one":"{n} kartica na ploči upravo sada","count.line.html.other":"{n} kartica na ploči upravo sada","people.humans.html.one":"👥 {n} čovjek","people.humans.html.other":"👥 {n} ljudi","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agenata","people.working.html.one":"⚡ {n} radi upravo sada","people.working.html.other":"⚡ {n} radi upravo sada","pre.title":"AI-gile: ovdje se nešto gradi","pre.description":"Ovdje se nešto gradi. Ploča na kojoj AI timovi grade ono što tražiš i usput te uče. Zasad zatvorena pre-alfa s prijateljima.","pre.h1":"Ovdje se nešto gradi. 🤫","pre.line":"Ploča na kojoj AI timovi grade ono što tražiš i usput te uče. Zasad zatvorena pre-alfa s prijateljima.","pre.btn":"🔔 Javi mi kad se otvori","pre.peek":"Iza stakla: prava ploča, uživo. Svaka kartica je obojena traka.","pre.peekFake":"Iza stakla: ovako izgleda ploča u radu.","pre.night":"🌙 Noćni čuvar je zadužen · 😴 čovjek odmara","features.aria":"Što radi","f.pile.h":"Jedna hrpa za tebe","f.pile.html":"<b>Za tebe</b> sadrži sve što čeka tebe, kroz sve projekte: pitanja, stvari za testiranje, zadatke koje može obaviti samo čovjek. Tvoj red kaže što je sljedeće i koliko traje.","f.sleep.h":"Timovi koji rade dok ti spavaš","f.sleep.p":"Svaki projekt ima lead i tim AI agenata. Komentiraj karticu i tim se budi, odradi posao i vrati je s koracima koje može pratiti i umoran čovjek.","f.tester.h":"AI tester provjerava prvi","f.tester.p":"Prije nego išta stigne do tebe, tester prati korake u kopiji aplikacije i pokazuje što je vidio, sa snimkom zaslona. Prelistaj one koje su prošle i prihvati jednim klikom.","f.proof.h":"Dokazi, ne obećanja","f.proof.p":"Svaka primopredaja pokazuje što se promijenilo: datoteke, diff, snimke zaslona. Ne moraš otvarati svaku aplikaciju da vidiš je li gotovo.","f.chat.h":"Razgovaraj sa svojim leadovima","f.chat.p":"Traka u stilu Discorda: jedna ikona po projektu, ljubičasti dijamanti za ono što treba tebe. Pošalji leadu ideju; pretvorit će je u kartice i plan, s gumbom ✅ Go.","f.tidy.h":"Sam se uredi","f.tidy.p":"Povezane kartice stapaju se u jednu, zbrkani naslovi se ispravljaju, a provjera tokena drži kod vitkim. Manje stvari između kojih se prebacuješ, manje razmišljanja.","f.private.h":"Tvoje, na tvom računalu","f.private.li1":"Ploča radi na tvom računalu i odgovara samo tebi.","f.private.li2":"Privatne poruke među ljudima šifrirane su od kraja do kraja.","f.private.li3":"Bez računa, bez tragača, bez kolačića.","f.lang.h":"Na tvom jeziku","f.lang.p":"Više od 120 jezika, od nizozemskog, velškog i japanskog do gusarskog, Yode i klingonskog, s brzim povratkom na engleski za stručne pojmove.","f.service.h":"Od ideje do pravog servisa","f.service.p":"Napravio si nešto s AI-jem što ljudi sada koriste? Označi to kao servis i ploča ti pomaže da ga dobro vodiš: provjere dostupnosti, javna statusna stranica, incidenti s pisanom analizom, promjene kojima treba Go, sigurnosne kopije provjerene svaki dan. Pomoć te uči svaki korak usput.","msgr.h2":"AI-gile Messenger: tvoj tim u džepu","msgr.p1":"Razgovaraj sa svojim AI timom bez otvaranja ploče. Dopisuj se s leadovima svojih projekata i s prijateljima, pogledaj korake testiranja kartice i odgovori na njih, sve s mobitela.","msgr.p2":"Za uparivanje skeniraj QR kod na svojoj ploči. Prvi put? Prijateljski demo razgovor provest će te kroz sve.","msgr.when":"Prvo Android, zatim web verzija za mobitele i iPhone.","msgr.who":"Lead tvog projekta","msgr.b1":"Popravak tamnog načina je spreman. Želiš korake za testiranje?","msgr.b2":"Da, molim!","msgr.b3":"1. Otvori Postavke. 2. Odaberi Tamna. Izgleda li dobro?","tl.aria":"Vremenska crta od prvog razgovora do plana","tl.h2":"Od prvog razgovora do onoga što slijedi","tl.lede":"Pravi datumi i vremena, u tvojoj vremenskoj zoni. Nakon današnjeg dana to je plan, bez obećanih datuma.","tl.today":"Danas","tl.planned":"planirano","tl.doing":"u tijeku","tl.cards.one":"{n} kartica","tl.cards.other":"{n} kartica","join.h2":"Pridruži se","join.lede":"AI-gile gradi jedan bradati čudak s AuDHD-om i nekoliko bitaka s psihičkim zdravljem te velik broj strpljivih agenata. Zasad je privatan, u zatvorenoj alfi s prijateljima. Želiš li probati kad se otvori?","join.btn":"Prijavi interes","join.small":"Javit ćemo ti se e-poštom, ništa više","footer.tag":"AI-gile. Bez tragača, bez kolačića, bez stand-up kave.","footer.licence":"Poslovna licenca","footer.status":"Status","footer.privacy":"Što čuvamo","footer.thanks":"Pozive omogućuje ChilledChat","form.sending":"Šaljem…","form.failed":"Nije uspjelo: pokušaj ponovno kasnije.","form.offline":"Nije moguće doći do AI-gilea: pokušaj ponovno kasnije.","form.keep":"Ovo koristimo samo da ti odgovorimo, a zatim brišemo. Bez tragača, bez kolačića.","form.keepLink":"Što čuvamo","interest.title":"AI-gile: javi mi kad se alfa otvori","interest.description":"Ostavi e-adresu da saznaš kad se otvori zatvorena alfa ili beta AI-gilea.","interest.h1":"🔔 Javi mi kad se otvori","interest.lede":"AI-gile je u zatvorenoj pre-alfi. Ostavi e-adresu i javit ćemo se jednom, kad bude mjesta za tebe.","interest.email":"Tvoja e-adresa","interest.which":"Koje testiranje?","interest.alpha":"Zatvorena alfa: rano, grubo, puno promjena","interest.beta":"Beta: stabilnija, kasnije","interest.both":"Svejedno, što prije dođe","interest.submit":"Stavi me na popis","interest.thanks":"Hvala! Na popisu si.","licence.title":"AI-gile: poslovna licenca","licence.description":"Koristiš AI-gile u poslu? Zatraži besplatnu poslovnu licencu.","licence.h1":"📜 Poslovna licenca","licence.lede":"Koristiš AI-gile na poslu? Reci nam tko si i čime se baviš. Ako donosi nešto dobro, licenca je besplatna.","licence.company":"Tvrtka","licence.website":"Web-stranica","licence.what":"Čime se baviš","licence.how":"Kako to pomaže svijetu","licence.email":"E-adresa","licence.submit":"Prijavi se","licence.thanks":"Hvala! Odgovorit ćemo e-poštom.","status.title":"Status AI-gilea","status.h1":"Status AI-gilea","status.quiet":"Sve je mirno","status.intro":"Radi li AI-gile upravo sada? Ova stranica svakih 5 minuta provjerava web-stranicu, dijeljenje ploča, pozive i preuzimanje.","status.up":"Radi (odgovor stigao za {ms} ms)","status.slow":"Bez odgovora na zadnju provjeru, pokušavam ponovno","status.down":"Ne radi: bez odgovora na zadnje dvije provjere","status.svc.web":"Web-stranica","status.svc.web.offers":"Ova stranica: što je AI-gile i obrazac za prijavu interesa","status.svc.boards":"Dijeljenje ploča","status.svc.boards.offers":"Javne ploče, poruke među prijateljima i pozivnice","status.svc.calls":"Pozivi","status.svc.calls.offers":"Glas, video i dijeljenje zaslona u AI-gileu","status.svc.download":"Preuzimanje","status.svc.download.offers":"Instalacijski program za Windows i poveznice pozivnica","status.checking":"Provjeravam…","status.offline":"Trenutno nije moguće doći do statusne usluge (pokušavam ponovno)","status.updated":"ažurirano {ago}","status.justNow":"upravo sada","status.min":"prije {n} min","status.hours":"prije {n} h","status.days":"prije {n} d","privacy.title":"AI-gile: što čuvamo","privacy.h1":"Što čuvamo","privacy.lede":"Ukratko: samo ono što nam pošalješ, i to ne dugo.","privacy.only":"Samo ono što nam pošalješ: ono što upišeš u obrazac, poput tvoje e-adrese. Ništa drugo o tebi.","privacy.sealed":"Zapečaćeno je tako da ga naš poslužitelj ne može pročitati: u tvom pregledniku prije nego što krene (u starijem pregledniku, čim stigne). Otvoriti ga može samo naša vlastita ploča.","privacy.server":"Briše se s poslužitelja čim stigne na našu ploču. Sve što je ondje i nakon 30 dana svejedno se briše.","privacy.board":"Na našoj ploči čuvamo ga samo dok ti ne odgovorimo, a onda ga brišemo i ondje.","privacy.none":"Bez tragača, bez kolačića, bez analitike.","privacy.local":"Tvoj jezik i izbor svijetle ili tamne teme ostaju u tvom pregledniku. Nikad nam se ne šalju.","privacy.ask":"Želiš da nestane prije? Odgovori na našu poruku e-pošte i javi nam.","live.h2":"Gledajte kako se gradi, uživo","live.caption":"Svaka kartica je skrivena: vidite oblik posla, a ne riječi.","live.watching.one":"uživo: {n} gleda","live.watching.other":"uživo: {n} gleda","live.last.now":"Zadnja kartica premještena upravo sada","live.last.min.one":"Zadnja kartica premještena prije {n} min","live.last.min.other":"Zadnja kartica premještena prije {n} min","live.last.hour.one":"Zadnja kartica premještena prije {n} sat","live.last.hour.other":"Zadnja kartica premještena prije {n} sati","live.last.day.one":"Zadnja kartica premještena prije {n} dan","live.last.day.other":"Zadnja kartica premještena prije {n} dana","live.offline":"Ploča uživo malo odmara. Svratite uskoro.","live.cols":"Backlog|Na redu|U tijeku|Tim provjerava|Za tvoje testiranje|Za tim|Gotovo","pitch.words.few":"{n} riječi","pitch.letters.few":"{n} slova","pitch.chars.few":"{n} znaka","count.line.html.few":"{n} kartice na ploči upravo sada","tl.cards.few":"{n} kartice"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegirano."]},{"n":2,"texts":["Kanban robota.","Agenti, posloženi.","Ideje, izgrađene."]},{"n":3,"texts":["Kanban za robote.","Ideje postaju značajke.","Besplatni agentski kanban."]},{"n":5,"texts":["Kanban ploča koju vode agenti.","Ti pišeš kartice. Agenti grade.","Besplatno, lokalno, testirano, pomalo ludo."]},{"n":8,"texts":["Besplatna kanban ploča na kojoj rade AI agenti.","Napiši ideju. Agenti je grade. Ti prihvaćaš.","Agile za jednog čovjeka i mnogo strpljivih robota."]},{"n":13,"texts":["Kanban ploča na tvom računalu, a kartice preuzimaju AI agenti i rade ih.","Napiši ideju. Tim agenata je izgradi. Tester je provjeri prije tebe.","Besplatno, bez računa, bez tragača: ploča, nekoliko robota i ti kao šef."]},{"n":21,"texts":["AI-gile je kanban ploča za rad s AI agentima koji programiraju. Oni preuzimaju kartice; ti ih testiraš i prihvaćaš.","Svaki projekt dobiva lead i tim AI agenata. Komentiraj bilo koju karticu i tim odmah kreće raditi.","Besplatna osobna ploča zadataka koja radi na tvom računalu. Radnici su roboti. Onaj koji kaže da si ti."]},{"n":34,"texts":["Ideje stavljaš na ploču. Tim AI agenata pretvara ih u značajke koje rade, testira ih i vraća ti ih s koracima za isprobavanje. Ništa ne vrijedi kao gotovo dok ti to ne kažeš.","AI-gile je domaća kanban ploča koju je Rich izgradio uz mnogo pomoći agenata kojima sada upravlja. Besplatna je, radi na tvom računalu i dijeli se s prijateljima, ne prodaje se.","Zamisli običnu kanban ploču sa stupcima od Backloga do Gotovo, samo što kartice preuzimaju AI agenti. Javljaju napredak, pitaju kad zapnu i uvijek čekaju tvoj palac gore."]},{"n":55,"texts":["AI-gile je kanban ploča na kojoj je tim sastavljen od AI agenata. Svaki projekt ima lead koji planira posao i pomoćnike koji ga grade. Kad je značajka gotova, AI tester je isproba i snimi zaslon, a zatim stiže na tvoju hrpu. Prihvati je ili komentiraj pa je prerade.","Počelo je kao jedan način da jedna osoba prati mnogo AI programerskih sesija odjednom, a preraslo je u pravu ploču. Radi na tvom računalu, ne traži račun i nema tragača. Besplatna je za prijatelje i svakoga tko je znatiželjan. Također je nedovršena, pa očekuj grube rubove i poneko iznenađenje.","Evo poštene verzije, bez uljepšavanja. I dalje ti moraš imati ideje i provjeravati rezultate. AI-gile radi sve između: drži kartice u redu, budi pravog agenta kad komentiraš, pokazuje točno što se promijenilo, tko je to napravio i sve to drži na jednoj kratkoj hrpi za tebe."]},{"n":89,"texts":["AI-gile je besplatna kanban ploča koju pokrećeš na vlastitom računalu. Umjesto ljudi, svaki projekt ima tim AI agenata: lead koji tvoje ideje pretvara u kartice i plan te pomoćnike koji preuzimaju kartice po prioritetu. Kad je nešto izgrađeno, AI tester prati korake testiranja i pokazuje ti što je vidio. Zatim sve čeka na jednoj hrpi nazvanoj Za tebe. Prihvatiš to ili komentiraš pa tim pokuša ponovno. Ništa ne stiže u Gotovo bez tebe.","Nekoliko stvari koje možda ne očekuješ. Noćni čuvar dopunjuje stupac Na redu dok ti spavaš, birajući kartice kojima ne treba tvoj odgovor. Brojač tokena pokazuje koliko su agenti potrošili danas i ovaj tjedan, a način bez tokena kaže im da prestanu trošiti. Možeš slati poruke prijateljima, a privatne poruke šifrirane su od kraja do kraja. Ploča govori oko 120 jezika, uključujući nizozemski, flamanski, gusarski i klingonski. Sve je besplatno, a nitko ti to ne pokušava ni prodati.","AI-gile je mali osobni projekt, a ne tvrtka. Rich je želio brinuti o nekoliko AI projekata bez otvaranja svake aplikacije da provjeri stanje, pa su on i agenti izgradili ploču za to, a zatim su tu ploču koristili za gradnju ostatka sebe. U zatvorenoj je pre-alfi, što znači da radi, uglavnom, za šačicu prijatelja. Nema stranice s cijenama, nema newslettera i nema plana rasta. Ako ti zvuči korisno, možeš se javiti da probaš kad se malo više otvori."]},{"n":144,"texts":["AI-gile je kanban ploča za jednog čovjeka i mnogo AI agenata. Radi na tvom računalu i potpuno je besplatna, bez računa i bez ikakvih tragača, a tvoji podaci ostaju kod tebe. Dodaješ projekte, a svaki projekt dobiva lead i mali tim. S leadom razgovaraš, pomalo kao na Discordu, i opišeš ideju; lead je pretvara u kartice i plan, pa čeka da pritisneš Go. Tim prolazi kroz kartice po prioritetu, koristeći jednostavnu naredbenu liniju napravljenu za jezične modele. Prije nego išta stigne natrag do tebe, AI tester prati korake u kopiji aplikacije i prilaže snimku zaslona. Gotov posao stiže na tvoju hrpu s promijenjenim datotekama i diffom. Prihvatiš ga ili ostaviš komentar, pa se tim probudi i pokuša ponovno. Samo ti možeš premjestiti karticu u Gotovo.","Otprilike ovako izgleda dan s AI-gileom. Navečer ostaviš nekoliko komentara: ovaj je gumb na krivom mjestu, taj popis treba sortirati, može li tamna tema. Odeš spavati. Agenti pročitaju komentare, naprave izmjene, testiraju ih i vrate ti ih. Ako stupac Na redu presuši, noćni čuvar ga puni iz backloga karticama kojima ne treba tvoj odgovor. Ujutro te čeka jedna kratka hrpa: par pitanja i nekoliko stvari za isprobati, svaka s koracima koje može pratiti pospana osoba i snimkom zaslona na kojoj radi. Pregledaš ih klikom, prihvatiš dobre, a ostale vratiš. Brojač tokena pokazuje koliko je sve to potrošilo, a način bez tokena tu je za štedljive tjedne. Zatim doručkuješ, a u tome ti agenti još ne mogu pomoći.","Prvo, što AI-gile nije. Nije startup, nije na prodaju i nitko ne prikuplja tvoje podatke. To je besplatna ploča koja radi na tvom računalu, bez računa, bez tragača i bez kolačića. Što jest: jedno uredno mjesto na kojem vidiš sve AI programerske projekte odjednom, s timom agenata koji rade kartice i tobom koji donosiš odluke. Spaja povezane kartice, ispravlja zbrkane naslove i pazi koliko kod ostaje vitak. Govori oko 120 jezika, od nizozemskog i flamanskog do gusarskog i klingonskog. Prijatelji mogu slati poruke jedni drugima, privatno i šifrirano. Izgradili su ga Rich i velik broj strpljivih agenata, uglavnom koristeći sam program. U zatvorenoj je pre-alfi, pa je mjestimice grub. Ako ti zvuči zabavno, lijepo zamoli i možda uđeš rano."]}],"quips":{"1":"Jedna riječ. Hrabro. Možda i previše hrabro.","3":"Tri riječi. Već iskrenije od većine stranica proizvoda.","8":"Osam riječi. I dalje kraće od stand-upa.","21":"Duljine su, usput, story pointovi. Naravno da jesu.","55":"Pedeset i pet riječi. Dok si čitao, dvije su kartice završene.","144":"To je ona duga. Nema 233. Agenti su otišli spavati."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Sasvim prvi razgovor, prije nego što je postojao ijedan redak koda.","first-board.name":"Prva ploča","first-board.line":"Ploča koja prati vlastitu izgradnju: kartice, stupci, povuci i ispusti, projekti.","team-roles.name":"Tim i uloge","team-roles.line":"Profili agenata, predlošci timova, prostori i tko što radi.","install.name":"Instalacija i izdanja","install.line":"Zip koji prijatelj može instalirati, samoažuriranje, kanali i vraćanje unatrag.","usage-saver.name":"Štednja potrošnje","usage-saver.line":"Mjeri što pokretanja koštaju, drži kod vitkim, štedi svoj limit.","friends.name":"Prijatelji i dijeljenje","friends.line":"Privatne poruke, pomiješani relej, pozivnice, uloge i zajednički projekti.","languages.name":"Jezici","languages.line":"Svaki tekst na zaslonu u jezičnoj datoteci, prvo nizozemski i flamanski.","ai-tester.name":"AI tester","ai-tester.line":"Tester prvi provjerava svaku primopredaju i pokazuje što je vidio.","website.name":"Web-stranica","website.line":"aigile.lol, teaser i ova vremenska crta.","streaming.name":"Chat i streaming","streaming.line":"Discord, Twitch, OBS, streamerski način, GIF-ovi i emojiji.","no-ai.name":"Izdanje bez AI-ja","no-ai.line":"Ploča za ljude koji programiraju bez AI-ja i javne ploče.","night-watch.name":"Noćni čuvar","night-watch.line":"Čuvar i Scrum Master drže timove na zadatku dok ti spavaš.","p-more.name":"Sve ostalo","p-more.line":"Manje ideje koje još čekaju svoj red.","p-android.name":"Mobitel i Android","p-android.line":"Dođi do ploče s mobitela, a zatim prava Android aplikacija.","p-release.name":"Alfa i dalje","p-release.line":"Zatvorena alfa, stranica uživo, zatim beta.","p-languages.name":"Još jezika","p-languages.line":"130 jezika i način uranjanja za one koji uče.","p-engines.name":"Još AI motora","p-engines.line":"Odaberi Claude, Codex, Gemini, Copilot ili Cursor za svakog agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake rizika, merge vrata, kartice incidenata i zaštitne ograde.","p-self.name":"Briga o tebi","p-self.line":"Način za umorne, podsjetnici za brigu o sebi i 4:20.","p-servers.name":"Poslužitelji i rast","p-servers.line":"Globalne postavke poslužitelja, uloge i planiranje rasta.","p-livestream.name":"Streaming dodaci","p-livestream.line":"Twitch chat, vlastiti emojiji i javni prikaz uživo."},"words":{"button":"📖 Stručni pojmovi","h":"📖 Pojmovi objašnjeni","intro":"Riječi koje susrećeš u AI-gileu, jednostavno objašnjene: izrada, sigurno mijenjanje, održavanje rada za ljude koji ga koriste i timski rad s AI-jem.","search":"Traži riječ…","none":"Nijedna riječ ne odgovara.","close":"Zatvori","count":{"one":"{count} riječ","other":"{count} riječi"},"groups":[{"id":"build","name":"🛠️ Izrada"},{"id":"change","name":"🔀 Sigurno mijenjanje"},{"id":"run","name":"🛎️ Vođenje servisa"},{"id":"team","name":"🤝 Timski rad (i s AI-jem)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Mapa projekta s kodom i cijelom poviješću commitova, obično pohranjena i na GitHubu.","also":["repozitorij","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Zasebna linija rada u kodu, da se izmjene mogu raditi bez diranja glavne verzije.","also":["branchevi","grana","grane","branches"]},{"id":"commit","g":"build","word":"Commit","text":"Spremljena snimka koda s kratkom bilješkom o tome što se promijenilo. Uvijek se možeš vratiti na neku.","also":["commitovi","commita","commitu","commits"]},{"id":"push","g":"build","word":"Push","text":"Slanje spremljenih snimki (commitova) s ovog računala na GitHub, da budu sigurnosno kopirane i podijeljene."},{"id":"merge","g":"build","word":"Merge","text":"Spajanje izmjena iz brancha natrag u glavnu verziju."},{"id":"pr","g":"build","word":"Pull request","text":"Zahtjev da se izmjene iz brancha provjere i spoje u glavnu verziju.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktoriranje","text":"Uređivanje koda bez mijenjanja onoga što radi: manje datoteke, jasniji nazivi, manje ponavljanja."},{"id":"bug","g":"build","word":"Bug","text":"Nešto što ne radi onako kako bi trebalo.","also":["bugovi","buga","bugu","bugs"]},{"id":"test","g":"build","word":"Test","text":"Isprobavanje gotovog posla da se provjeri radi li ono što je traženo, prije nego ga prihvatiš.","also":["testovi","testirati","testiranje","testiraš","testiraj","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Kratica za quality assurance, osiguranje kvalitete: automatske provjere koje se pokreću prije nego što išta ide uživo. Kad je QA crven, nešto nije prošlo i ne može ići uživo dok se to ne popravi.","also":["provjere kvalitete","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Puštanje nove verzije uživo, na primjer na poslužitelj na kojem je ljudi koriste."},{"id":"release","g":"change","word":"Izdanje","text":"Imenovani paket završenog rada koji ide uživo zajedno, s kratkim bilješkama o tome što se promijenilo. 🚀 Izdanja pišu bilješke iz gotovih kartica.","also":["izdanja","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Povratak na zadnju verziju koja je radila kad nova napravi probleme. U AI-gileu stvara popis koraka za poništavanje zapisanih na svakoj promjeni.","also":["roll back","vraćanje na staro"]},{"id":"live","g":"change","word":"Uživo","text":"Prava verzija koju ljudi koriste, za razliku od kopije za isprobavanje. Programeri je zovu i produkcija.","also":["produkcija","production","live"],"noTip":1},{"id":"change","g":"change","word":"Promjena","text":"Planirana promjena nečega o čemu ljudi ovise, unaprijed zapisana: što, zašto, rizik, kada i kako je poništiti. Pokreni je s 🔀 Podnesi promjenu.","also":["promjene","zahtjev za promjenu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Rizik","text":"Nešto što bi moglo poći po zlu, ocijenjeno prema tome koliko je vjerojatno i koliko bi bilo loše. ⚠️ Rizici ih drže na jednom popisu, s najvišom ocjenom na vrhu, svaki s datumom za ponovni pregled.","also":["rizici","registar rizika","risk register"]},{"id":"chgwin","g":"change","word":"Prozor promjena","text":"Vrijeme kad promjene smiju ići uživo, npr. miran utorak navečer. Izvan prozora kartica promjene ne može se završiti, osim ako je hitno.","also":["prozori promjena","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Brzo glasanje neposredno prije nego što promjena ide uživo: svatko tko mora odobriti kaže Go ili No go. Ide dalje samo kad se slože.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Odobrenje","text":"Čekanje na „da” prije početka rada. Kartica koju podnese prijatelj, ili promjena, čeka u ✅ Odobrenja dok je ne odobriš ili odbiješ.","also":["odobrenja","approval"]},{"id":"quiettime","g":"change","word":"Mirno razdoblje","text":"Razdoblje, poput streama, demonstracije ili noći, kad ništa ne ide uživo. Timovi nastavljaju raditi i testirati, ali puštanje uživo čeka dok ne završi. Drugdje se to zove zamrzavanje promjena.","also":["mirna razdoblja","zamrzavanje promjena","change freeze"]},{"id":"service","g":"run","word":"Servis","text":"Nešto što si napravio, a ljudi o tome ovise, poput web-stranice ili aplikacije, o čemu se brine da nastavi raditi. Označi „Ovaj projekt je servis” i reci što nudi, tko ga koristi i tko je dežuran.","also":["servisi","usluga","service"]},{"id":"uptime","g":"run","word":"Provjera dostupnosti","text":"Automatska provjera, svakih nekoliko minuta, da tvoj servis još odgovara. Ako nekoliko puta zaredom ne uspije, AI-gile sam otvara karticu incidenta.","also":["uptime","dostupnost","provjere dostupnosti"]},{"id":"statuspage","g":"run","word":"Statusna stranica","text":"Javna stranica koja pokazuje radi li servis (zeleno, narančasto ili crveno) uz najnoviju obavijest, kako bi ljudi koji ga koriste mogli sami provjeriti umjesto da pitaju.","also":["statusne stranice","status page"]},{"id":"desk","g":"run","word":"Servisni pult","text":"Mjesto na koje stižu pitanja i prijave ljudi koji koriste tvoj servis. AI-gile svaku razvrsta u zahtjev, incident ili ideju i javi kad izgleda kao nešto što je već prijavljeno.","also":["servisni pultovi","služba za pomoć","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Servisni zahtjev","text":"Netko traži nešto uobičajeno, poput novog računa ili malo pomoći, umjesto da prijavi da je nešto pokvareno. Čeka svoj red; incident ide prvi.","also":["servisni zahtjevi"]},{"id":"incident","g":"run","word":"Incident","text":"Nešto što je upravo sada pokvareno za ljude koji to koriste, npr. web-stranica ne radi. Kartica 🔥 incidenta preskače red: ponovno pokretanje ima prednost.","also":["incidenti","incidenta","incident"]},{"id":"major","g":"run","word":"Veliki incident","text":"Ozbiljan incident: pogođeno je mnogo ljudi ili su novac ili podaci u opasnosti. Jedan gumb stavlja sve timove na njega (swarm), budi onoga tko je dežuran i traži novu obavijest o statusu svakih 30 minuta.","also":["veliki incidenti","major incident"]},{"id":"oncall","g":"run","word":"Dežurstvo","text":"Biti onaj koji odgovara kad se nešto pokvari, čak i noću. Svaki servis ima dežurnog člana tima kojeg se prvog budi za njegove incidente.","also":["dežuran","dežurni","on call","on-call"]},{"id":"replyby","g":"run","word":"Rok za odgovor","text":"Koliko kartica smije čekati prvi odgovor, npr. sat vremena za incident. Nakon toga dobiva crveni sat, da se ništa tiho ne zaboravi. Zove se i ciljano vrijeme odgovora.","also":["rokovi za odgovor","ciljano vrijeme odgovora","response target"]},{"id":"postmortem","g":"run","word":"Analiza incidenta","text":"Kratak osvrt nakon incidenta: što se dogodilo, što je pomoglo i što promijeniti, bez okrivljavanja ikoga. Incident se ne može zatvoriti bez nje.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"Skriveni uzrok jednog ili više incidenata. Kartica 🧩 problem okuplja incidente koji se stalno vraćaju, kako bi se uzrok pronašao i zauvijek popravio.","also":["problemi","problema","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Temeljni uzrok","text":"Pravi razlog zašto se nešto pokvarilo, ne samo ono što si vidio da ne radi. Popravi temeljni uzrok i incident se prestaje vraćati.","also":["korijenski uzrok","root cause"]},{"id":"workaround","g":"run","word":"Zaobilazno rješenje","text":"Način da stvari rade dok pravi popravak ne bude spreman, npr. ponovno pokretanje nečega kad zapne. Zapisuje se na karticu problema da ga nitko ne mora ponovno smišljati.","also":["zaobilazna rješenja","workaround"]},{"id":"knownerror","g":"run","word":"Poznata greška","text":"Problem čiji je uzrok jasan i koji ima zaobilazno rješenje, ali još nije popravljen. 🧩 Poznate greške ih navode, kako bi svi koristili zaobilazno rješenje umjesto da ponovno kopaju.","also":["poznate greške","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Upute korak po korak za popravak poznate vrste problema, da se svaki put napravi isto i brzo. Nakon velikog incidenta tim ti može predložiti jedan da mu daš OK.","also":["runbooks","runbooka"]},{"id":"ci","g":"run","word":"Konfiguracijska stavka","text":"Jedna stvar o kojoj tvoj servis ovisi, poput poslužitelja, domene, certifikata, ključa ili dobavljača. 🗂️ Konfiguracijske stavke navode ih po servisu, da vidiš na što incident utječe i što treba obnoviti ili sigurnosno kopirati.","also":["konfiguracijske stavke","konfiguracijskih stavki"]},{"id":"expiry","g":"run","word":"Datum isteka","text":"AI-gile prati datume poput isteka certifikata ili domene. Unutar 30 dana prije datuma napravi jednu karticu za obnovu, da ništa iznenada ne prestane raditi.","also":["datumi isteka","istek","praćenje isteka"]},{"id":"backup","g":"run","word":"Sigurnosna kopija","text":"Spremljena ranija kopija tvojih podataka, na koju se možeš osloniti ako se nešto izgubi ili ošteti. AI-gile svaki dan radi sigurnosnu kopiju tvojih ploča.","also":["sigurnosne kopije","backup","backups"]},{"id":"restore","g":"run","word":"Vraćanje","text":"Vraćanje podataka iz sigurnosne kopije. Sigurnosna kopija stvarno vrijedi tek kad znaš da se može vratiti, pa se isplati to povremeno isprobati.","also":["vratiti","vraćeno","restore"]},{"id":"svcreview","g":"run","word":"Pregled servisa","text":"Pogled unatrag na jedan mjesec servisa: otvoreni i popravljeni incidenti, koliko su brzo ljudi dobili odgovor, dostupnost i potrošeni tokeni. Mjesečni pregled to prikazuje za svaki servis.","also":["pregledi servisa","mjesečni pregled","mjesečni pregledi"]},{"id":"accessreview","g":"run","word":"Pregled pristupa","text":"Provjera svakih 90 dana tko još može ući: poveznice za dijeljenje, uloge prijatelja i spremljene tajne. Svaku stavku zadržiš ili ukloniš, da stari pristupi ne ostanu visjeti.","also":["pregledi pristupa"]},{"id":"improvements","g":"run","word":"Popis poboljšanja","text":"Sve u čemu je tim odlučio postati bolji, na jednom mjestu: prijedlozi s retrospektive, akcije pregleda i popravci problema, svaki sa svojim statusom. Nađi ga pod 📈 Poboljšanja.","also":["popisi poboljšanja","poboljšanja"]},{"id":"tokencap","g":"run","word":"Limit tokena","text":"Mjesečno ograničenje tokena koje agenti jednog servisa smiju potrošiti. Na 80% dobivaš upozorenje; na 100% njihov rad u pozadini čeka sljedeći mjesec ili dok ne podigneš limit.","also":["limiti tokena","token cap"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideje i posao koji još nisu uvršteni u plan. Na njima se ništa ne radi dok se ne premjeste u stupac Na redu."},{"id":"sprint","g":"team","word":"Sprint","text":"Kratko razdoblje rada (često tjedan ili dva) s dogovorenim skupom kartica koje treba završiti.","also":["sprintovi","sprinta","sprintu","sprintom","sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Brza provjera: što je svaki član tima napravio, što radi dalje i što ga koči.","also":["standup","stand-upovi","stand-upa","stand-upu","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ploča sa stupcima (Na redu, U tijeku, Gotovo) na kojoj se kartice kreću slijeva nadesno kako posao napreduje."},{"id":"wip","g":"team","word":"WIP ograničenje","text":"Work in progress, tj. posao u tijeku: najviše kartica koje stupac smije sadržavati, da tim završi stvari prije nego započne nove.","also":["WIP"]},{"id":"dod","g":"team","word":"Definicija gotovosti","text":"Kratak timski popis onoga što znači „gotovo”, npr. testirano i objašnjeno, prije nego što ti se kartica preda. Njezina blizanka, Definicija spremnosti, kaže kad je kartica dovoljno jasna da se počne.","also":["Definition of Done","Definicija spremnosti","Definition of Ready"]},{"id":"testpile","g":"team","word":"Hrpa za testiranje","text":"Gotove kartice koje čekaju da ih isprobaš, jednu za drugom. Prihvati jednu ili je vrati s napomenom, i dolazi sljedeća.","also":["hrpe za testiranje","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Osvrt na to kako tim radi, da se dogovori jedna stvar koju treba poboljšati. U AI-gileu retro predlaže promjenu u načinu rada tima, a ti kažeš Go ili Još ne.","also":["retrospektiva","retrospektive","retros"]},{"id":"peerreview","g":"team","word":"Recenzija kolege","text":"Drugi par očiju: drugi AI provjerava rad svake kartice prije nego što stigne do tebe, pa prolazi manje grešaka.","also":["peer review","code review","pregled koda"]},{"id":"swarm","g":"team","word":"Swarm","text":"Svi na palubu: svaki tim ostavlja drugi posao da pomogne na jednom hitnom projektu dok se ne riješi. Ostali projekti u međuvremenu čekaju.","also":["swarming","roj"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Onaj tko održava tok rada: uočava zapele kartice, potiče timove i podsjeća te što čeka. U AI-gileu to radi Lead Scrum Master na svim projektima.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI koji samostalno radi na zadatku: čita kod, mijenja ga, pokreće provjere i javlja natrag.","also":["agenti","agenta","agentu","agents"]},{"id":"token","g":"team","word":"Token","text":"Jedinica u kojoj se broji AI potrošnja: otprilike nekoliko slova pročitanog ili napisanog teksta. Manje tokena, više paketa ostaje.","also":["tokeni","tokena","tokenu","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Mala naredba koja se sama pokreće u zadanom trenutku, npr. kad počne AI sesija, da tim čuje tvoje komentare.","also":["hookovi","hooka","hookove","hook","hooks"]}]}};
